CREATE TABLE IF NOT EXISTS club_messages(message_id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL,thread_id INTEGER NOT NULL,text TEXT NOT NULL,parent_id INTEGER,kind TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS club_messages_time ON club_messages(created_at);
CREATE TABLE IF NOT EXISTS club_reactions(message_id INTEGER NOT NULL,user_id INTEGER NOT NULL,PRIMARY KEY(message_id,user_id));
CREATE TABLE IF NOT EXISTS club_controls(user_id INTEGER PRIMARY KEY,prompts INTEGER NOT NULL DEFAULT 1,last_nudge INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS fan_interests(user_id INTEGER PRIMARY KEY,interests TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS club_jobs(id INTEGER PRIMARY KEY AUTOINCREMENT,job_key TEXT UNIQUE NOT NULL,kind TEXT NOT NULL,data TEXT NOT NULL,thread_id INTEGER NOT NULL DEFAULT 0,user_id INTEGER,state TEXT NOT NULL DEFAULT 'pending',run_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,message_id INTEGER);
CREATE INDEX IF NOT EXISTS club_jobs_due ON club_jobs(state,run_at);
CREATE TABLE IF NOT EXISTS club_events(id INTEGER PRIMARY KEY,title TEXT NOT NULL,creator INTEGER NOT NULL,thread_id INTEGER NOT NULL,starts_at INTEGER,location TEXT NOT NULL DEFAULT 'To be decided',source_url TEXT,status TEXT NOT NULL DEFAULT 'draft',date_options TEXT NOT NULL DEFAULT '[]',poll_id TEXT,message_id INTEGER,created_at INTEGER NOT NULL,confirmed_by INTEGER);
CREATE TABLE IF NOT EXISTS club_rsvps(event_id INTEGER NOT NULL,user_id INTEGER NOT NULL,response TEXT NOT NULL,remind INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(event_id,user_id));
CREATE TABLE IF NOT EXISTS club_date_votes(event_id INTEGER NOT NULL,user_id INTEGER NOT NULL,option_id INTEGER NOT NULL,PRIMARY KEY(event_id,user_id));
CREATE TABLE IF NOT EXISTS club_reviews(id INTEGER PRIMARY KEY AUTOINCREMENT,message_id INTEGER UNIQUE NOT NULL,user_id INTEGER NOT NULL,thread_id INTEGER NOT NULL,reason TEXT NOT NULL,suggestion TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'pending',action TEXT,approved_by INTEGER,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS club_memory(id INTEGER PRIMARY KEY,title TEXT NOT NULL,body TEXT NOT NULL,kind TEXT NOT NULL,source_message INTEGER,source_thread INTEGER NOT NULL DEFAULT 0,proposed_by INTEGER NOT NULL,approved_by INTEGER,status TEXT NOT NULL DEFAULT 'pending',created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS club_games(id INTEGER PRIMARY KEY,kind TEXT NOT NULL,thread_id INTEGER NOT NULL,state TEXT NOT NULL DEFAULT 'open',step INTEGER NOT NULL DEFAULT 0,opened_at INTEGER NOT NULL,ends_at INTEGER NOT NULL,message_id INTEGER,payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS club_game_polls(poll_id TEXT PRIMARY KEY,game_id INTEGER NOT NULL,round INTEGER NOT NULL,correct INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS club_game_answers(game_id INTEGER NOT NULL,round INTEGER NOT NULL,user_id INTEGER NOT NULL,correct INTEGER NOT NULL,PRIMARY KEY(game_id,round,user_id));
CREATE TABLE IF NOT EXISTS club_teams(user_id INTEGER PRIMARY KEY,team TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS club_points(event_key TEXT PRIMARY KEY,user_id INTEGER NOT NULL,team TEXT,points INTEGER NOT NULL,kind TEXT NOT NULL,season TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS club_captions(game_id INTEGER NOT NULL,user_id INTEGER NOT NULL,text TEXT NOT NULL,PRIMARY KEY(game_id,user_id));
CREATE TABLE IF NOT EXISTS club_caption_votes(game_id INTEGER NOT NULL,user_id INTEGER NOT NULL,candidate INTEGER NOT NULL,PRIMARY KEY(game_id,user_id));
